sp_widget.client_script:
(function() {
    api.controller = function($scope, $http) {
        $scope.approvals = [];

        function loadApprovals() {
            var request = {
                method: 'GET',
                url: '/api/now/table/sysapproval_approver', // Corrected table
                params: {
                    sysparm_query: 'state=requested^approver=' + $scope.user.sys_id,
                    sysparm_fields: 'sys_id,sysapproval.short_description,state,sys_updated_on',
                    sysparm_limit: 10
                }
            };

            $http(request).then(function(response) {
                $scope.approvals = response.data.result;
            }, function(error) {
                console.error("Error fetching approvals", error);
            });
        }

        $scope.processApproval = function(sys_id, action) {
            var request = {
                method: 'POST',
                url: '/api/now/ui/widget/your_widget_id',
                data: {
                    action: action,
                    sys_id: sys_id
                }
            };

            $http(request).then(function(response) {
                alert(response.data.result.message);
                loadApprovals();
            }, function(error) {
                console.error("Error processing approval", error);
            });
        };

        loadApprovals();
    };
})();

sp_widget.css:
.hr-approval-status {
    padding: 15px;
}

.hr-approval-status ul {
    list-style: none;
    padding: 0;
}

.hr-approval-status li {
    background: #f8f9fa;
    padding: 10px;
    margin: 5px 0;
    border-radius: 5px;
}

.badge {
    background: #ffc107;
    padding: 5px 10px;
    border-radius: 5px;
    margin-left: 10px;
}

.btn-sm {
    float: right;
}

sp_widget.script:
(function() {
    data.approvals = [];

    var gr = new GlideRecord('sysapproval_approver'); // Corrected table name
    gr.addQuery('state', 'requested');
    gr.addQuery('approver', gs.getUserID());
    gr.query();

    while (gr.next()) {
        data.approvals.push({
            sys_id: gr.getValue('sys_id'),
            short_description: gr.getValue('sysapproval.short_description'), // Get from parent
            state: gr.getValue('state'),
            updated_on: gr.getValue('sys_updated_on')
        });
    }

    // Handle Approval Action
    if (input && input.action && input.sys_id) {
        var actionGr = new GlideRecord('sysapproval_approver'); // Use correct table
        if (actionGr.get(input.sys_id)) {
            actionGr.state = input.action === 'approve' ? 'approved' : 'rejected';
            actionGr.update();
            data.message = "Approval " + input.action + "d successfully.";
        }
    }
})();
